                    float(self.aapl_rsi.Current.Value) > self.RSI_THRESHOLD
                )
            else:
                strategy_b_sell = False

            strategy_b_buy = self.aapl_red_streak >= 3

            if self.strategy_b_shares > 0 and strategy_b_sell:
                self.MarketOrder(self.aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

            if self.strategy_b_shares == 0 and strategy_b_buy:
