        spy_current_sma = sum(list(self.spy_closes)[-100:]) / 100.0
        spy_previous_sma = sum(list(self.spy_closes)[-101:-1]) / 100.0

        aapl_current_close = self.aapl_closes[-1]
        aapl_previous_close = self.aapl_closes[-2]

        aapl_red_streak = (
            self.aapl_closes[-1] < self.aapl_closes[-2]
            and self.aapl_closes[-2] < self.aapl_closes[-3]
            and self.aapl_closes[-3] < self.aapl_closes[-4]
        )

        if self.strategy_a_lot > 0:
            if (
                spy_previous_close <= spy_previous_sma
                and spy_current_close > spy_current_sma
            ):
                pass

            if (
                spy_previous_close >= spy_previous_sma
                and spy_current_close < spy_current_sma
            ):
                self.MarketOrder(
                    self.symbols["SPY"],
                    -self.strategy_a_lot,
                    tag="Strategy A liquidation"
                )
                self.strategy_a_lot = 0

        if self.strategy_b_lot > 0:
            if self.aapl_rsi.Current.Value > 70:
                self.MarketOrder(
                    self.symbols["AAPL"],
                    -self.strategy_b_lot,
                    tag="Strategy B liquidation"
                )
                self.strategy_b_lot = 0

        if self.strategy_a_lot == 0:
            if (
                spy_previous_close <= spy_previous_sma
                and spy_current_close > spy_current_sma
            ):
                target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                quantity = int(target_value / spy_current_close)

                if quantity > 0:
                    self.MarketOrder(
                        self.symbols["SPY"],
                        quantity,
                        tag="Strategy A buy"
                    )
                    self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0:
            if aapl_red_streak and self.Portfolio.Cash >= 20000:
                quantity = int(20000 / aapl_current_close)

                if quantity > 0:
                    self.MarketOrder(
                        self.symbols["AAPL"],
                        quantity,
                        tag="Strategy B buy"
                    )
                    self.strategy_b_lot = quantity

from AlgorithmImports import *
from collections import deque
import math


class ExactStrategySystem(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_closes = deque(maxlen=101)
        self.aapl_closes = deque(maxlen=2)

        self.aapl_red_streak = 0
        self.a_lot = 0
        self.b_lot = 0

        self.rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

    def OnData(self, data: Slice):
        for symbol in self.symbols.values():
            if not data.Bars.ContainsKey(symbol):
                return

        spy_bar = data.Bars[self.spy]
        aapl_bar = data.Bars[self.aapl]

        spy_close = float(spy_bar.Close)
        aapl_close = float(aapl_bar.Close)

        if self.spy_closes:
            previous_spy_close = self.spy_closes[-1]
            previous_spy_sma = (
                sum(list(self.spy_closes)[-100:]) / 100
                if len(self.spy_closes) >= 100
                else None
            )
        else:
            previous_spy_close = None
            previous_spy_sma = None

        previous_aapl_close = (
            self.aapl_closes[-1] if self.aapl_closes else None
        )

        self.spy_closes.append(spy_close)
        self.aapl_closes.append(aapl_close)

        self.rsi.Update(aapl_bar.EndTime, aapl_close)

        if previous_aapl_close is not None:
            if aapl_close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        if len(self.spy_closes) < 100 or previous_spy_sma is None or not self.rsi.IsReady:
            return

        current_spy_sma = sum(self.spy_closes) / 100
        spy_crossed_above = (
            previous_spy_close <= previous_spy_sma
            and spy_close > current_spy_sma
        )
        spy_crossed_below = (
            previous_spy_close >= previous_spy_sma
            and spy_close < current_spy_sma
        )

        aapl_rsi_above_threshold = self.rsi.Current.Value > 70

        if self.a_lot > 0 and spy_crossed_below:
            self.MarketOrder(self.spy, -self.a_lot)
            self.a_lot = 0

        if self.b_lot > 0 and aapl_rsi_above_threshold:
            self.MarketOrder(self.aapl, -self.b_lot)
            self.b_lot = 0

        if self.a_lot == 0 and spy_crossed_above:
            target_value = 0.40 * self.Portfolio.TotalPortfolioValue
            quantity = int(math.floor(target_value / spy_close))
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.a_lot = quantity

        if self.b_lot == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
                quantity = int(math.floor(20000 / aapl_close))
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.b_lot = quantity
